import WhyChooseUs from "../components/WhyChooseUs";
export default function About() {
  return (
    <div className="container py-5">
      <h2 className="fw-bold mb-3">About Intative Technology</h2>
      <p className="text-muted">
        We are a technology-driven company specializing in custom websites, web applications,
        and software solutions tailored to business needs.
      </p>
      <p>At Intative Technology, we empower businesses with cutting-edge IT solutions designed to accelerate growth and efficiency. Specializing in custom software development, digital transformation, and technology consulting, we craft innovative solutions tailored to your unique needs. Our team of skilled professionals leverages advanced technologies and industry best practices to deliver seamless, secure, and high-performing applications. From strategic planning to execution, we ensure that every solution we create drives measurable results, enhances user experience, and strengthens your competitive edge. Partner with us to transform your vision into reality with reliable, future-ready IT services that keep your business ahead of the curve.</p>
      <p>
        Our focus is performance, security, and long-term scalability — not shortcuts.
      </p>
      <WhyChooseUs />

    </div>
  );
}
